INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',842,'{"_type":"chat:Message","id":"8641420749:1922","threadId":"telegram:8641420749","text":"Push the same session than yesterday to Garmin for today and everyday until saturday","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Push the same session than yesterday to Garmin for today and everyday until saturday","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":85,"offset":84}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":85,"offset":84}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":85,"offset":84}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-28T06:03:38.000Z","edited":false},"attachments":[],"isMention":false}',1791180218112);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',843,'{"_type":"chat:Message","id":"8641420749:1925","threadId":"telegram:8641420749","text":"Je viens d''arriver au col de la Lombarde, 20 km en 2 h 28. Je me suis à peine arrêté. J''ai dû m''arrêter même pas 10 minutes max : une fois 3 minutes, une fois 5 minutes, 6 minutes pour remplir les bouteilles et une fois 2 minutes pour pisser. J''ai dû passer quasiment tout le temps en zone 3, zone 4.\n\nJe me suis senti super bien, j''ai super bien géré la nutrition et j''ai alterné debout-assis. Super sensation, là, je suis au top. Je vais continuer. Par contre j''ai un peu peur de la descente, où je vais me refroidir, ou éventuellement du genou qui chauffe, parce qu''il travaille plus. Qu''est-ce que tu me conseilles en termes de nutrition pour me couvrir, quoi que ce soit, pour protéger le genou, continuer à être bien et pas exploser ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je viens d''arriver au col de la Lombarde, 20 km en 2 h 28. Je me suis à peine arrêté. J''ai dû m''arrêter même pas 10 minutes max : une fois 3 minutes, une fois 5 minutes, 6 minutes pour remplir les bouteilles et une fois 2 minutes pour pisser. J''ai dû passer quasiment tout le temps en zone 3, zone 4.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":301,"offset":300}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":301,"offset":300}}},{"type":"paragraph","children":[{"type":"text","value":"Je me suis senti super bien, j''ai super bien géré la nutrition et j''ai alterné debout-assis. Super sensation, là, je suis au top. Je vais continuer. Par contre j''ai un peu peur de la descente, où je vais me refroidir, ou éventuellement du genou qui chauffe, parce qu''il travaille plus. Qu''est-ce que tu me conseilles en termes de nutrition pour me couvrir, quoi que ce soit, pour protéger le genou, continuer à être bien et pas exploser ?","position":{"start":{"line":3,"column":1,"offset":302},"end":{"line":3,"column":439,"offset":740}}}],"position":{"start":{"line":3,"column":1,"offset":302},"end":{"line":3,"column":439,"offset":740}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":3,"column":439,"offset":740}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-09-28T16:21:41.000Z","edited":false},"attachments":[],"isMention":false}',1791217301973);
