INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',847,'{"_type":"chat:Message","id":"8641420749:1933","threadId":"telegram:8641420749","text":"I made it to Napoli. You can find all the adventure on Strava if you’re interested","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"I made it to Napoli. You can find all the adventure on Strava if you’re interested","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":83,"offset":82}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":83,"offset":82}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":83,"offset":82}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-04T07:38:31.000Z","edited":false},"attachments":[],"isMention":false}',1791713874542);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',848,'{"_type":"chat:Message","id":"8641420749:1939","threadId":"telegram:8641420749","text":"Merci pour tes félicitations ! Je suis vraiment content de cette année d’entrainement, des efforts de renfo musculaire, de ma discipline. Ça a vraiment payé ! Je me suis senti super bien et je n’ai pas eu de problèmes de genoux. J’ai surtout confirmé que je suis vraiment fort pour grimper, je me faisais parfois doubler par d’autres participants surtout le plat, avec mon velo en acier Temple Cycles Adventure Disc 2 et eux avec leur velo en carbone. Mais par contre je les explosais dans les montées. L’entraînement a bien payé pour ça.","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Merci pour tes félicitations ! Je suis vraiment content de cette année d’entrainement, des efforts de renfo musculaire, de ma discipline. Ça a vraiment payé ! Je me suis senti super bien et je n’ai pas eu de problèmes de genoux. J’ai surtout confirmé que je suis vraiment fort pour grimper, je me faisais parfois doubler par d’autres participants surtout le plat, avec mon velo en acier Temple Cycles Adventure Disc 2 et eux avec leur velo en carbone. Mais par contre je les explosais dans les montées. L’entraînement a bien payé pour ça.","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":539,"offset":538}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":539,"offset":538}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":539,"offset":538}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-05T10:05:57.000Z","edited":false},"attachments":[],"isMention":false}',1791799557349);
INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',849,'{"_type":"chat:Message","id":"8641420749:1941","threadId":"telegram:8641420749","text":"Pour la suite, je rentre aujourd’hui à la maison et je veux recuperer au mieux, en favorisant sommeil, nutrition et active recovery. Dimanche prochain dans 6 jours j’ai la course Subida da Rampa do Vale de Santo Antonio, c’est 500m de sprint en montée sur des pavés avec un passage à 16%. On commence à 200m du debut sur l’image suivante","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Pour la suite, je rentre aujourd’hui à la maison et je veux recuperer au mieux, en favorisant sommeil, nutrition et active recovery. Dimanche prochain dans 6 jours j’ai la course Subida da Rampa do Vale de Santo Antonio, c’est 500m de sprint en montée sur des pavés avec un passage à 16%. On commence à 200m du debut sur l’image suivante","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":338,"offset":337}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":338,"offset":337}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":338,"offset":337}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-05T10:10:36.000Z","edited":false},"attachments":[{"type":"image","size":119833,"width":965,"height":1280,"fetchMetadata":{"fileId":"AgACAgQAAxkBAAIHlWrDd5xXQD2o-gpyODKu1l4K4zZ2AAJZEGsbAuEgUur5uiD90rZ4AQADAgADeQADPQQ"}}],"isMention":false}',1791799835697);
