INSERT INTO chat_sdk_lists VALUES('msg-history:telegram:8641420749',855,'{"_type":"chat:Message","id":"8641420749:1964","threadId":"telegram:8641420749","text":"Je remonte mon velo à la maison. La chaine est bien crade. Vu que je l’ai démonté pour proteger le derailleur, je veux en profiter pour nettoyer la chaine hors du velo. Comment faire ?","formatted":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","value":"Je remonte mon velo à la maison. La chaine est bien crade. Vu que je l’ai démonté pour proteger le derailleur, je veux en profiter pour nettoyer la chaine hors du velo. Comment faire ?","position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":185,"offset":184}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":185,"offset":184}}}],"position":{"start":{"line":1,"column":1,"offset":0},"end":{"line":1,"column":185,"offset":184}}},"raw":null,"author":{"userId":"8641420749","userName":"Clément","fullName":"Clément de Coligny","isBot":false,"isMe":false},"metadata":{"dateSent":"2026-10-05T16:38:08.000Z","edited":false},"attachments":[],"isMention":false}',1791823089082);
